<?php
namespace App\Services;
use App\Contracts\FoundationSkDocumentWriter; use App\Models\{FoundationSkDocument,User}; use Illuminate\Support\Facades\{DB,Storage};
class FoundationSkDocumentWriterImplementation implements FoundationSkDocumentWriter { public function __construct(private FoundationSkDocumentService $service){} public function createOrUpdate(User $user,int $year,int $templateId,string $path,array $metadata,User $actor):FoundationSkDocument{return DB::transaction(function()use($user,$year,$templateId,$path,$metadata,$actor){$key=['user_id'=>$user->id,'tahun_sk'=>$year,'sk_template_id'=>$templateId];$doc=FoundationSkDocument::query()->where($key)->lockForUpdate()->first();$data=$key+['original_filename'=>$metadata['original_filename']??basename($path),'stored_filename'=>$metadata['stored_filename']??basename($path),'file_path'=>$path,'mime_type'=>$metadata['mime_type']??'application/pdf','file_size'=>$metadata['file_size']??Storage::disk('documents')->size($path),'source_type'=>$metadata['source_type']??'generated','matched_by'=>$metadata['matched_by']??'generated','uploaded_by'=>$actor->id];if($doc){$doc->update($data);return $doc->fresh();}return FoundationSkDocument::create($data);});} public function deleteFile(?string $path):void{if($path)Storage::disk('documents')->delete($path);} public function storeFile(string $path,string $contents):bool{return Storage::disk('documents')->put($path,$contents);} public function cleanupFiles(array $paths):void{foreach($paths as $p)$this->deleteFile($p);} }
